import time
from collections import deque

class SlidingWindowLogLimiter:
    def __init__(self, max_requests=5, window_seconds=60.0):
        # Strict type validation
        if isinstance(max_requests, bool) or not isinstance(max_requests, int):
            raise ValueError("max_requests must be an integer")
        if isinstance(window_seconds, bool) or not isinstance(window_seconds, (int, float)):
            raise ValueError("window_seconds must be a number")

        if max_requests < 0:
            raise ValueError("max_requests cannot be negative")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be positive")

        self.max_requests = max_requests
        self.window_seconds = window_seconds
        # Store a deque of timestamps for each key
        self.requests_log = {}

    def allow(self, key, now=None):
        if now is None:
            now = time.time()

        # Validate 'now'
        if isinstance(now, bool) or not isinstance(now, (int, float)):
            raise ValueError("now must be a number or None")

        if key is None or isinstance(key, bool) or not isinstance(key, (str, int)):
             # Allowing str and int as keys is standard, rejecting complex objects for safety/simplicity
             raise ValueError("key must be a string or integer")

        if key not in self.requests_log:
            self.requests_log[key] = deque()

        log = self.requests_log[key]
        window_start = now - self.window_seconds

        # Evict expired requests from the front of the deque
        while log and log[0] <= window_start:
            log.popleft()

        # Check if within limit
        if len(log) < self.max_requests:
            log.append(now)
            return True, len(log)
        else:
            return False, len(log)

